//! Cargo-driven `m.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is m-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "Entry"),
        "x86_64" => ("x86_64-pc-windows-gnu", "Entry"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "Entry"),
        o => panic!("m-cargo: unsupported arch {o}"),
    };

    Linker::new(target_json)
        .rust_staticlib("m-rust")
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}

